        let start = src.find(sig).expect("must find sig");
        let rest = &src[start..];
        let end = rest[1..]
            .find("\n    pub fn ")
            .or_else(|| rest[1..].find("\n    pub(crate) fn "))
            .or_else(|| rest[1..].find("\n    fn "))
            .map(|i| 1 + i)
            .unwrap_or(rest.len());
        let body = &rest[..end];

